  {
   "speaker": "Client",
   "act": "state",
   "content": [
    "The Function Codes used in association with Maintenance Services Team Numbers (CT=6) shall conform to table 9A-2."
   ]
  },
  {
   "speaker": "Analyst",
   "act": "anything_else"
  }
 ],
 "turns": [
  {
   "id": "M1:T101",
   "speaker": "Client",
   "act": "nothing_else",
   "guide": "Short answer: nothing else on this topic."
  },
  {
   "id": "M1:T102",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'access classes' and asks about it."
  },
  {
   "id": "M1:T103",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "For consistent working on public networks and in international roaming, the use of access classes in a railway network shall comply with the GSM specification.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T104",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'functional numbering' and asks about it."
  },
  {
   "id": "M1:T105",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Mobile access to the functional numbering scheme for registration, deregistration and re-registration shall apply the USSD messages and protocols over the air interface as specified in the GSM Follow-me service.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T106",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "In the event of a registration procedure failing owing to the functional number already being registered to another mobile, the Cab radio shall be capable of providing the user with the ability to perform automatically the forced de-registration of the previously registered mobile and the registration of this functional number to the user's mobile.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T107",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The functionality described in 11.3.9i should also be available for other types of mobiles.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T108",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Re-registration of on-train functional numbers based on the train number shall be performed every time a train leaves one EIRENE network and enters into another EIRENE network.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T109",
   "speaker": "Analyst",
   "act": "anything_else",
   "guide": "Analyst asks whether there is anything else on 'functional numbering'."
  },
  {
   "id": "M1:T110",
   "speaker": "Client",
   "act": "nothing_else",
   "guide": "Short answer: nothing else on this topic."
  },
  {
   "id": "M1:T111",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 're-establishment of functional number correlation' and asks about it."
  },
  {
   "id": "M1:T112",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "In the event of losing correlation between functional numbers and MSISDNs, provision for recovery from such a situation shall be made.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T113",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'presentation of functional identities' and asks about it."
  },
  {
   "id": "M1:T114",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The calling party functional number shall be passed to the receiving mobile using the User to User Signalling supplementary service (UUS1) during call setup.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T115",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'inter eirene network interfacing' and asks about it."
  },
  {
   "id": "M1:T116",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The protocol used for routing of calls shall be Signalling System No 7 (SS7) as defined by the ITU-T.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T117",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Call setup between EIRENE networks using international functional numbers shall be based on the combination of the Breakout-Code (BC) and International Code (IC) as specified in section 9.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T118",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T119",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'provision of railway emergency calls' and asks about it."
  },
  {
   "id": "M1:T120",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "It shall be possible to configure Railway emergency group call areas to contain combinations of cells controlled by one or more MSC(s) within one or more network(s).",
     "role": "statement"
    }
   ]
  }
 ]
